// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Montserrat');

// Load Montserrat 900 at module level for a solid bold cinematic letter style
const { fontFamily } = loadFont("normal", {
  weights: ["900"],
});



export type FlickerTitleProps = Record<string, any>;

const FlickerTitle: React.FC<FlickerTitleProps> = ({
  text = "OBSESSION",
  nextTextLine1 = "ONLY IN THEATERS",
  nextTextLine2 = "MAY 15",
  fontScale = 1.0,
  stretchY = 1.3,
  letterSpacingScale = 1.0,
  skewX = -8.0,
  primaryColor = "#ffffff",
  glowColorLeft = "#00bfff",
  glowColorRight = "#ff4500",
  flickerSpeed = 1.0,
  noiseIntensity = 0.8,
  crtOverlay = true,
  backgroundColor = "#020205",
  transparentBackground = false,
  durationInSeconds = 8,
  transitionPoint = 0.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const progress = frame / totalFrames;

  // Resolve backgrounds dynamically for safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Identify active screen based on the transition point
  const isScreen2 = progress >= transitionPoint;

  // Normalize progress for each screen state
  const p1 = Math.min(1, progress / transitionPoint);
  const p2 = isScreen2 ? (progress - transitionPoint) / (1 - transitionPoint) : 0;

  // Global stabilization factor to transition into a solid, fully lit state towards the end of Screen 1
  const solidFactor = interpolate(p1, [0.7, 0.88], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Screen 2 stabilization factor (re-ignites neon quickly and then holds)
  const solidFactor2 = interpolate(p2, [0.0, 0.25], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Global Analog Camera Jitter
  const cameraShakeX = (random(`camera-shake-x-${frame}`) - 0.5) * 2.5 * noiseIntensity;
  const cameraShakeY = (random(`camera-shake-y-${frame}`) - 0.5) * 1.5 * noiseIntensity;

  // Violent camera shake, skew, and flash offsets decaying quickly post-transition
  let extraShakeX = 0;
  let extraShakeY = 0;
  let extraSkew = 0;
  let transitionFlash = 0;

  if (progress >= transitionPoint && progress < transitionPoint + 0.08) {
    const tProgress = (progress - transitionPoint) / 0.08;
    const shakeAmp = interpolate(tProgress, [0, 1], [40, 0]) * noiseIntensity;
    extraShakeX = (random(`trans-shake-x-${frame}`) - 0.5) * shakeAmp;
    extraShakeY = (random(`trans-shake-y-${frame}`) - 0.5) * shakeAmp;
    extraSkew = (random(`trans-skew-${frame}`) - 0.5) * interpolate(tProgress, [0, 1], [15, 0]);
    transitionFlash = interpolate(tProgress, [0, 0.4, 1], [0.8, 0.4, 0]);
  }

  // Global Glitch/Power Surge Trigger (Periodic instability)
  const glitchPeriod = Math.floor(frame / 5);
  const globalGlitchRand = random(`global-glitch-${glitchPeriod}`);
  const activeSolidFactor = isScreen2 ? solidFactor2 : solidFactor;
  const isGlobalGlitch = globalGlitchRand > 0.92 && activeSolidFactor < 1;

  const globalGlitchShakeX = isGlobalGlitch
    ? (random(`glitch-shake-x-${frame}`) - 0.5) * 18 * noiseIntensity
    : 0;
  const globalGlitchShakeY = isGlobalGlitch
    ? (random(`glitch-shake-y-${frame}`) - 0.5) * 12 * noiseIntensity
    : 0;

  // Cinematic slow zoom
  const cameraZoom = isScreen2
    ? interpolate(p2, [0, 1], [1.0, 1.06], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
    : interpolate(p1, [0, 1], [0.96, 1.02], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Calculate dynamic typography parameters
  const baseFontSize = width * 0.08 * fontScale;
  const letterSpacing = width * 0.009 * letterSpacingScale;

  // Dynamic overall text brightness for ambient background reflection
  let avgOpacity = 0;
  if (!isScreen2) {
    const letters = text.split("");
    const totalOpacity = letters.reduce((acc, char, i) => {
      if (char === " ") return acc;
      const letterStartProgress = i * 0.04;
      const localProgress = Math.max(0, Math.min(1, (p1 - letterStartProgress) / 0.4));
      const flickerFrame = Math.floor(frame * flickerSpeed * 0.8);
      const randVal = random(`letter-${i}-${flickerFrame}`);
      let opacity = 1.0;
      if (localProgress < 0.95) {
        if (randVal < 0.28 * (1 - localProgress)) opacity = 0.04;
        else if (randVal < 0.58 * (1 - localProgress)) opacity = 0.25;
      } else {
        const stableGlitchRand = random(`stable-glitch-${i}-${flickerFrame}`);
        if (stableGlitchRand > 0.98) opacity = 0.08;
        else if (stableGlitchRand > 0.95) opacity = 0.4;
      }
      opacity = interpolate(solidFactor, [0, 1], [opacity, 1.0]);
      return acc + opacity;
    }, 0);
    avgOpacity = letters.length > 0 ? totalOpacity / letters.length : 0;
  } else {
    const lines = [nextTextLine1, nextTextLine2];
    let totalOpacitySum = 0;
    let totalLetterCount = 0;
    lines.forEach((lineText) => {
      const letters = lineText.split("");
      letters.forEach((char, i) => {
        if (char === " ") return;
        totalLetterCount++;
        const uniqueId = `${lineText}-${i}`;
        const letterStartProgress = i * 0.03;
        const localProgress = Math.max(0, Math.min(1, (p2 - letterStartProgress) / 0.35));
        const flickerFrame = Math.floor(frame * flickerSpeed * 0.8);
        const randVal = random(`letter-${uniqueId}-${flickerFrame}`);
        let opacity = 1.0;
        if (localProgress < 0.95) {
          if (randVal < 0.28 * (1 - localProgress)) opacity = 0.04;
          else if (randVal < 0.58 * (1 - localProgress)) opacity = 0.25;
        } else {
          const stableGlitchRand = random(`stable-glitch-${uniqueId}-${flickerFrame}`);
          if (stableGlitchRand > 0.985) opacity = 0.08;
          else if (stableGlitchRand > 0.96) opacity = 0.4;
        }
        opacity = interpolate(solidFactor2, [0, 1], [opacity, 1.0]);
        totalOpacitySum += opacity;
      });
    });
    avgOpacity = totalLetterCount > 0 ? totalOpacitySum / totalLetterCount : 0;
  }

  // Move refresh scanline downwards across screen
  const scanlineY = interpolate(frame % (fps * 4), [0, fps * 4], [-200, height + 200]);

  // Reusable cinematic flickering line generator
  const renderCinematicLine = (
    lineText: string,
    lineSolidFactor: number,
    lineProgress: number,
    lineFontScale: number
  ) => {
    const letters = lineText.split("");
    const lineBaseFontSize = baseFontSize * lineFontScale;

    return letters.map((char, i) => {
      if (char === " ") {
        return (
          <span
            key={`space-${i}`}
            style={{
              display: "inline-block",
              width: lineBaseFontSize * 0.32,
              transition: "none",
            }}
          />
        );
      }

      const uniqueId = `${lineText}-${i}`;
      const letterStartProgress = i * 0.03;
      const localProgress = Math.max(
        0,
        Math.min(1, (lineProgress - letterStartProgress) / 0.35)
      );

      const flickerFrame = Math.floor(frame * flickerSpeed * 0.8);
      const randVal = random(`letter-${uniqueId}-${flickerFrame}`);

      let opacity = 1.0;
      let isOverdrive = false;

      if (localProgress < 0.95) {
        if (randVal < 0.28 * (1 - localProgress)) {
          opacity = 0.04;
        } else if (randVal < 0.58 * (1 - localProgress)) {
          opacity = 0.25;
        } else if (randVal > 0.93) {
          isOverdrive = true;
        }
      } else {
        const stableGlitchRand = random(`stable-glitch-${uniqueId}-${flickerFrame}`);
        if (stableGlitchRand > 0.985) {
          opacity = 0.08;
        } else if (stableGlitchRand > 0.96) {
          opacity = 0.4;
        } else if (stableGlitchRand < 0.015) {
          isOverdrive = true;
        }
      }

      if (isGlobalGlitch) {
        const globalDropout = random(`global-dropout-${uniqueId}-${frame}`);
        if (globalDropout > 0.5) {
          opacity = opacity * 0.15;
        }
      }

      opacity = interpolate(lineSolidFactor, [0, 1], [opacity, 1.0]);
      if (lineSolidFactor === 1) {
        isOverdrive = false;
      }

      const letterScaleProgress = Math.min(1, localProgress * 1.5);
      const letterScale = interpolate(letterScaleProgress, [0, 1], [0.85, 1.0]);

      const letterJitterX = (random(`letter-jitter-x-${uniqueId}-${frame}`) - 0.5) * 3.5 * noiseIntensity;
      const letterJitterY = (random(`letter-jitter-y-${uniqueId}-${frame}`) - 0.5) * 1.8 * noiseIntensity;

      const shadowXLeft = -4.5 - cameraShakeX * 0.6 - letterJitterX;
      const shadowYLeft = -cameraShakeY * 0.6 - letterJitterY;
      const shadowXRight = 4.5 + cameraShakeX * 0.6 + letterJitterX;
      const shadowYRight = cameraShakeY * 0.6 + letterJitterY;

      const glowBlur = isOverdrive ? 28 : 12;
      const coreGlowColor = isOverdrive ? "#ffffff" : "rgba(255, 255, 255, 0.85)";

      const textShadow = [
        `${shadowXLeft}px ${shadowYLeft}px ${glowBlur}px ${glowColorLeft}`,
        `${shadowXRight}px ${shadowYRight}px ${glowBlur}px ${glowColorRight}`,
        `0 0 18px ${coreGlowColor}`,
      ].join(", ");

      return (
        <span
          key={i}
          style={{
            display: "inline-block",
            color: primaryColor,
            fontSize: lineBaseFontSize,
            fontWeight: 900,
            opacity: opacity,
            textShadow,
            transform: `skewX(${skewX + extraSkew}deg) scaleX(${letterScale}) scaleY(${letterScale * stretchY})`,
            margin: `0 ${letterSpacing}px`,
            transformOrigin: "center bottom",
            transition: "none",
            userSelect: "none",
            lineHeight: "1.0",
          }}
        >
          {char}
        </span>
      );
    });
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Ambient background reflection driven by text luminance */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle, rgba(255, 255, 255, ${0.06 * avgOpacity}) 0%, transparent 70%)`,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Main Title Container with cinematic transforms */}
      <div
        style={{
          display: "flex",
          flexDirection: isScreen2 ? "column" : "row",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${cameraZoom}) translate(${cameraShakeX + globalGlitchShakeX + extraShakeX}px, ${cameraShakeY + globalGlitchShakeY + extraShakeY}px)`,
          transition: "none",
          width: "100%",
          padding: "0 5%",
          gap: isScreen2 ? `${height * 0.04}px` : "0px",
        }}
      >
        {!isScreen2 ? (
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "center",
              alignItems: "center",
              flexWrap: "wrap",
              transition: "none",
            }}
          >
            {renderCinematicLine(text, solidFactor, p1, 1.0)}
          </div>
        ) : (
          <>
            {/* Screen 2 Line 1 (ONLY IN THEATERS) - beautifully scaled to fit cinematic screen */}
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "center",
                alignItems: "center",
                flexWrap: "wrap",
                transition: "none",
              }}
            >
              {renderCinematicLine(nextTextLine1, solidFactor2, p2, 0.85)}
            </div>

            {/* Screen 2 Line 2 (MAY 15) - massive date overlay matching the reference image */}
            <div
              style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "center",
                alignItems: "center",
                flexWrap: "wrap",
                transition: "none",
              }}
            >
              {renderCinematicLine(nextTextLine2, solidFactor2, p2, 1.35)}
            </div>
          </>
        )}
      </div>

      {/* Cinematic Glitch Flash Overlay */}
      {transitionFlash > 0 && (
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: `rgba(255, 255, 255, ${transitionFlash})`,
            mixBlendMode: "overlay",
            pointerEvents: "none",
            zIndex: 8,
          }}
        />
      )}

      {/* Vintage CRT Scanner Overlay */}
      {crtOverlay && (
        <>
          {/* CRT Horizontal Scanlines */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.18) 0px, rgba(0, 0, 0, 0.18) 2px, transparent 2px, transparent 4px)",
              pointerEvents: "none",
              zIndex: 10,
            }}
          />

          {/* Dynamic Refresh Bar Accent */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: scanlineY,
              height: 140,
              background:
                "linear-gradient(to bottom, transparent, rgba(255, 255, 255, 0.04), transparent)",
              pointerEvents: "none",
              zIndex: 9,
            }}
          />

          {/* Screen Vignette for analog depth */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(circle, transparent 35%, rgba(0, 0, 0, 0.75) 100%)",
              pointerEvents: "none",
              zIndex: 11,
            }}
          />
        </>
      )}
    </AbsoluteFill>
  );
};

export default FlickerTitle;